<script lang="ts">
  import {onMount} from 'svelte';
  import Icon from './Icon.svelte';
  let {value=$bindable(),id='tax-splits'}:{value?:unknown;id?:string}=$props();
  let rows:{tax_rate:string;net_amount:string;tax_amount:string}[]=$state([]);
  onMount(()=>{if(Array.isArray(value))rows=value.map(row=>({tax_rate:String(row.tax_rate??''),net_amount:String(row.net_amount??''),tax_amount:String(row.tax_amount??'')}));});
  $effect(()=>{value=rows.length?rows.map(row=>({...row})):undefined;});
</script>
<fieldset class="tax-splits"><legend class="field-label">Steueraufteilung bei gemischter Teilzahlung · nur falls erforderlich</legend><p class="field-help">Nur für einen Teilbetrag auf eine Anzahlungs- oder Abschlagsanforderung mit mehreren Steuerfällen. Übernehmen Sie die ausdrücklich bestätigten Netto- und Steueranteile aus Ihrer Buchungsgrundlage. Bei einem einzigen Steuerfall oder vollständiger Zahlung des Originals bleibt diese Liste leer.</p>{#each rows as row,index}<div class="tax-split-row"><div class="field"><label for={`${id}-rate-${index}`}>Steuersatz · % *</label><input id={`${id}-rate-${index}`} bind:value={row.tax_rate} inputmode="decimal" required/></div><div class="field"><label for={`${id}-net-${index}`}>Nettoanteil *</label><input id={`${id}-net-${index}`} bind:value={row.net_amount} inputmode="decimal" required/></div><div class="field"><label for={`${id}-tax-${index}`}>Steueranteil *</label><input id={`${id}-tax-${index}`} bind:value={row.tax_amount} inputmode="decimal" required/></div><button type="button" class="icon-button" aria-label={`Steueranteil ${index+1} entfernen`} onclick={()=>rows=rows.filter((_,i)=>i!==index)}><Icon name="trash" size={15}/></button></div>{/each}<button type="button" class="btn small mt" onclick={()=>rows=[...rows,{tax_rate:'',net_amount:'',tax_amount:''}]}><Icon name="plus" size={14}/>Bestätigten Steueranteil ergänzen</button></fieldset>
<style>.tax-splits{border:1px solid var(--line);border-radius:6px;padding:16px;min-width:0}.tax-splits legend{padding:0 5px}.tax-split-row{display:grid;grid-template-columns:1fr 1fr 1fr 35px;gap:10px;align-items:end;margin-top:18px}.tax-split-row>.icon-button{margin-bottom:5px}@media(max-width:760px){.tax-split-row{grid-template-columns:1fr 1fr;gap:12px}.tax-split-row>.icon-button{justify-self:end}.tax-splits{padding:14px}}</style>
